@Service
public class PaymentGatewayClient {

    private final Counter paymentFailures;

    public PaymentGatewayClient(MeterRegistry registry) {
        this.paymentFailures = Counter.builder("payment.gateway.failures")
                .description("Nombre d'appels échoués au fournisseur de paiement")
                .register(registry);
    }

    public PaymentResponse charge(ChargeRequest request) {
        try {
            return callExternalGateway(request);
        } catch (GatewayException e) {
            paymentFailures.increment();
            throw e;
        }
    }
}

